// Function to compare two header arrays
int compare_headers(const struct header *a, const struct header *b) {
    // Compare the number of headers (assuming it's known or can be determined)
    // For this example, we'll assume a fixed number of headers
    int header_count = 5; // Example value, adjust as needed

    for (int i = 0; i < header_count; i++) {
        if (a[i].key == NULL && b[i].key == NULL) {
            continue;
        }
        if (a[i].key == NULL || b[i].key == NULL) {
            return 0;
        }
        if (strcmp(a[i].key, b[i].key) != 0) {
            return 0;
        }
        if (strcmp(a[i].value, b[i].value) != 0) {
            return 0;
        }
    }
    return 1;
}

int update_or_add_device(struct device **device_list, const struct header *headers, time_t t) {
    // Check for null pointers
    if (device_list == NULL || headers == NULL) {
        return -1;
    }

    struct device *current = *device_list;
    struct device *prev = NULL;

    // Iterate through the device list to find a matching device
    while (current != NULL) {
        if (compare_headers(headers, current->headers)) {
            // Update the timestamp
            current->timestamp = t;
            // Reallocate memory if needed for the new location header
            // (Assuming we need to update a specific header, e.g., 'Location')
            // For this example, we'll assume a fixed header index for 'Location'
            int location_header_index = 3; // Example value, adjust as needed

            // Check if the 'Location' header exists in the headers array
            if (headers[location_header_index].value != NULL) {
                // Check if the current device's 'Location' header is different
                if (strcmp(current->headers[location_header_index].value, headers[location_header_index].value) != 0) {
                    // Free the old 'Location' header value
                    free(current->headers[location_header_index].value);

                    // Allocate memory for the new 'Location' header value
                    size_t new_value_length = strlen(headers[location_header_index].value) + 1;
                    current->headers[location_header_index].value = malloc(new_value_length);
                    if (current->headers[location_header_index].value == NULL) {
                        return -1;
                    }

                    // Copy the new 'Location' header value
                    strcpy(current->headers[location_header_index].value, headers[location_header_index].value);
                }
            }
            return 0; // Existing device updated
        }
        prev = current;
        current = current->next;
    }

    // No matching device found, create a new one
    struct device *new_device = malloc(sizeof(struct device));
    if (new_device == NULL) {
        return -1;
    }

    // Allocate memory for the headers
    int header_count = 5; // Example value, adjust as needed
    new_device->headers = malloc(header_count * sizeof(struct header));
    if (new_device->headers == NULL) {
        free(new_device);
        return -1;
    }

    // Initialize the new device's headers
    for (int i = 0; i < header_count; i++) {
        // Allocate memory for each header key and value
        if (headers[i].key != NULL) {
            size_t key_length = strlen(headers[i].key) + 1;
            new_device->headers[i].key = malloc(key_length);
            if (new_device->headers[i].key == NULL) {
                // Free previously allocated memory and return -1
                for (int j = 0; j < i; j++) {
                    free(new_device->headers[j].key);
                    free(new_device->headers[j].value);
                }
                free(new_device->headers);
                free(new_device);
                return -1;
            }
            strcpy(new_device->headers[i].key, headers[i].key);
        } else {
            new_device->headers[i].key = NULL;
        }

        if (headers[i].value != NULL) {
            size_t value_length = strlen(headers[i].value) + 1;
            new_device->headers[i].value = malloc(value_length);
            if (new_device->headers[i].value == NULL) {
                // Free previously allocated memory and return -1
                for (int j = 0; j < i; j++) {
                    free(new_device->headers[j].key);
                    free(new_device->headers[j].value);
                }
                free(new_device->headers);
                free(new_device);
                return -1;
            }
            strcpy(new_device->headers[i].value, headers[i].value);
        } else {
            new_device->headers[i].value = NULL;
        }
    }

    new_device->timestamp = t;
    new_device->next = NULL;

    // Add the new device to the list
    if (prev == NULL) {
        *device_list = new_device;
    } else {
        prev->next = new_device;
    }

    // Send notifications for new devices (implementation not provided)

    return 1; // New device added
}
